const sqlite3 = require('C:/Users/trong/AppData/Local/Programs/cursor/resources/app/node_modules/@vscode/sqlite3/lib/sqlite3');
const dbPath = 'C:/Users/trong/AppData/Roaming/Cursor/User/globalStorage/state.vscdb';
