const db = new sqlite3.Database(dbPath, sqlite3.OPEN_READONLY, function (err) {
  if (err) {
    console.error('DB open error:', err.message);
    process.exit(1);
  }

  db.get('SELECT value FROM ItemTable WHERE key = ?', [key], function (err2, row) {
    if (err2 || !row) {
      console.error('Query error:', err2 && err2.message);
      process.exit(1);
    }
    const data = JSON.parse(row.value);
    function walk(obj, path) {
      if (!obj || typeof obj !== 'object') return;
      for (const k of Object.keys(obj)) {
        const v = obj[k];
        const p = path ? path + '.' + k : k;
        if (/auto|run|diff|approval|permission|yolo|sandbox|inline|manual|allowlist/i.test(k)) {
          console.log(p + ' = ' + JSON.stringify(v));
        }
        if (v && typeof v === 'object' && !Array.isArray(v) && path.split('.').length < 4) {
          walk(v, p);
        }
      }
    }
    walk(data, '');
    db.close();
  });
});

